 const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const img = new Image();
    img.src = URL.createObjectURL(file);

    img.onload = () => {
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d")!;
      canvas.width = img.width;
      canvas.height = img.height;

      // วาดภาพลง canvas
      ctx.drawImage(img, 0, 0);

      // ดึง pixel data
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      // ปรับ grayscale + contrast
      const contrast = 50; // เพิ่ม contrast 50%
      const factor = (259 * (contrast + 255)) / (255 * (259 - contrast));

      for (let i = 0; i < data.length; i += 4) {
        // Grayscale
        const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
        data[i] = avg;
        data[i + 1] = avg;
        data[i + 2] = avg;

        // Contrast
        data[i] = factor * (data[i] - 128) + 128;
        data[i + 1] = factor * (data[i + 1] - 128) + 128;
        data[i + 2] = factor * (data[i + 2] - 128) + 128;
      }

      ctx.putImageData(imageData, 0, 0);

      // แปลงเป็น Blob สำหรับอัปโหลด
      canvas.toBlob((blob) => {
        if (blob) {
          const processedFile = new File([blob], file.name, { type: "image/jpeg" });
          console.log("Processed image ready to upload:", processedFile);
          // ส่ง processedFile ไป OCR หรือ API
             setSelectedFile(processedFile);
        }
      }, "image/jpeg", 0.9);
    };


   

      event.target.value = "";

  }}
  };

  const handleUpload = () => {

    if (selectedFile && onUpload) onUpload(selectedFile);
    setSelectedFile(null)
  }

  return (
    <Box
      sx={{
        border: "2px dashed #ccc",
        borderRadius: 4,
        p: 3,
        textAlign: "center",
        backgroundColor: "#fafafa",
      }}
    >
      {/* <Typography variant="h6" sx={{ mb: 2 }}>
        อัปโหลดสลิปโอนเงิน
      </Typography> */}

      <input
        accept="image/*"
        style={{ display: "none" }}
        id="upload-slip"
        type="file"
        onChange={handleFileChange}
      />

      <label htmlFor="upload-slip">
        <Button
          variant="contained"
          component="span"
          startIcon={<CloudUploadIcon />}
          sx={{
            backgroundColor: "#6c63ff",
            color: "#fff",
            textTransform: "none",
            borderRadius: 3,
            px: 3,
            py: 1.5,
            margin: 1,
            width: 150,
            "&:hover": { backgroundColor: "#5a54d6" },
          }}
        >
          เลือกไฟล์
        </Button>
      </label>

      {selectedFile && (
        <Typography variant="body2" sx={{ mt: 2, color: "#333" }}>
          ✅ {selectedFile.name}
        </Typography>
      )}

      {selectedFile &&
        <Button
          variant="contained"
          component="span"
          startIcon={<Save />}
          sx={{
            backgroundColor: "#1a924cff",
            color: "#fff",
            textTransform: "none",
            borderRadius: 3,
            px: 3,
            py: 1.5,
            margin: 1,
            width: 150,
            "&:hover": { backgroundColor: "#7dd654ff" },
          }}
          onClick={() => { handleUpload() }}
        >
          บันทึก
        </Button>}


    </Box>
  );
};

export default UploadSlip;
